const step15 = node({"type": "n8n-nodes-base.code", "version": 2, "config": {"name": "Add all-inclusive price", "position": [3360, 0], "parameters": {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "const contexts=$('Verify supplier quote').all();\nreturn $input.all().flatMap((item,i)=>{\n  const c=contexts[i]?.json, r=item.json;\n  if(!c || !c.offers?.[0])return [];\n  const o=c.offers[0], selected=c.selectedRoom;\n  let allInclusive={status:'unknown',totalDKK:null,roomName:null};\n  if(selected?.boardBasis==='AI')allInclusive={status:'included',totalDKK:o.total_price,roomName:selected.roomName};\n  else if(!r.failure && r.basketId===c.basketId && Array.isArray(r.data) && r.data.length===1 && r.data[0].roomIndex===0) {\n    const rooms=r.data[0].roomInfo?.availableHotelRooms;\n    if(Array.isArray(rooms) && rooms.length) {\n      const current=rooms.find(x=>x.roomId===selected?.roomId)?.availableBoards?.find(x=>x.boardSelect===selected?.boardSelect);\n      if(current && typeof current.upgradePriceInLocaleCurrency==='number' && Number.isFinite(current.upgradePriceInLocaleCurrency)) {\n        const options=[];let unknown=false;\n        for(const room of rooms) {\n          if(!Array.isArray(room.availableBoards)){unknown=true;continue;}\n          for(const board of room.availableBoards) {\n            if(board.boardBasis!=='AI')continue;\n            if(typeof board.availability!=='number'){unknown=true;continue;}\n            if(board.availability<=0)continue;\n            const delta=board.upgradePriceInLocaleCurrency;\n            if(typeof delta!=='number' || !Number.isFinite(delta)){unknown=true;continue;}\n            const total=o.total_price+delta-current.upgradePriceInLocaleCurrency;\n            if(Number.isFinite(total) && total>0)options.push({totalDKK:Math.ceil(total),roomName:room.roomName,roomChanged:room.roomId!==selected.roomId});\n          }\n        }\n        options.sort((a,b)=>a.totalDKK-b.totalDKK);\n        if(options.length)allInclusive={status:'available',...options[0]};\n        else if(!unknown)allInclusive={status:'unavailable',totalDKK:null,roomName:null};\n      }\n    }\n  }\n  const {boardCookie,basketId,boardOptionsUrl,selectedRoom,...result}=c;\n  return [{json:{...result,offers:[{...o,allInclusive}]}}];\n});\n"}}, "output": [{"preferences": {"childrenBirthDates": [], "windowDays": 60, "minNights": 7, "maxNights": 14, "maxTotalDKK": 10000, "maxPerPersonNightDKK": 350, "minStars": 4, "minGuestRating": 8.4, "maxAirportKm": 80, "maxBeachMetres": 1000, "maxDeals": 3, "minPriceDropPercent": 5, "minDaytimeC": 25, "minSunshineHours": 6, "maxRainProbabilityPercent": 30, "maxRainMmPerDay": 1, "maxWindKmh": 30, "maxHistoricalWetFraction": 0.2, "weatherMode": "seasonal_allowed", "includeAllInclusivePrice": true, "preferenceQuery": "Family-friendly hotel with a pool for children and a nearby beach"}, "message": "Family holiday deals", "url": "https://www.afbudsrejser.dk/charter.json", "offers": [], "redirectUrl": "https://www.afbudsrejser.dk/charterredirect", "providerUrl": "https://www.solfaktor.dk/example", "quoteUrl": "https://www.solfaktor.dk/custom-api/yggdrasil/basket/getPackage", "quoteBody": {}, "weatherUrl": "https://api.open-meteo.com/v1/forecast", "boardOptionsUrl": "https://www.solfaktor.dk/custom-api/yggdrasil/basket/getHotelRooms", "boardCookie": "", "embeddingEnabled": true, "embeddingBody": {"model": "embedding", "encoding_format": "float", "input": ["sample query", "sample hotel"]}, "id": "sample", "channel_id": "wxrgwf839tddxyrunhbo8ernqr", "delivered": true}]});
const step16 = node({"type": "n8n-nodes-base.code", "version": 2, "config": {"name": "Prepare hotel preference search", "position": [3600, 0], "parameters": {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Only public hotel text reaches the local embedding endpoint; exact offer\n// identities stay beside the workflow and are never inferred from similarity.\nconst rows=$input.all(), query=rows[0]?.json.request?.preferences?.preferenceQuery || '';\nif(typeof query!=='string' || query.length>500 || /[\\r\\n\\x00-\\x1f]/.test(query))throw Error('Invalid descriptive travel preference');\nconst bounded=(value,maximum=1700)=>{\n  const text=String(value??'').replace(/<[^>]*>/g,' ').replace(/\\s+/g,' ').trim();\n  let result='';\n  for(const c of text){if(Buffer.byteLength(result+c,'utf8')>maximum)break;result+=c;}\n  return result;\n};\nconst identity=(r,o)=>JSON.stringify([o.id,o.hotel?.id,o.supplier?.code,o.providerUrl,o.origin?.dt,o.return?.dt,r.request?.ageString]);\nconst candidates=[],seen=new Set();\nif(query.trim())for(const row of rows){\n  const r=row.json;\n  for(const o of r.offers || []){\n    if(!o.supplierVerified || typeof o.hotel?.id!=='string' || typeof o.providerUrl!=='string' || !o.providerUrl.startsWith('https://www.solfaktor.dk/'))continue;\n    const id=identity(r,o);\n    if(seen.has(id))continue;\n    seen.add(id);\n    candidates.push({id,text:bounded([o.hotel.name,o.hotel.description,o.hotel.room_name,o.destination?.name,\n      o.destination?.country_name,...(Array.isArray(o.metabool)?o.metabool:[])].filter(x=>typeof x==='string').join('. '))});\n  }\n}\n// Supplier verification is deliberately capped at six upstream. Do not make\n// a partial semantic ranking if that contract changes.\nconst enabled=Boolean(query.trim() && candidates.length && candidates.length<=6);\nconst instruction='Instruct: Given family holiday preferences, retrieve hotel descriptions matching the requested atmosphere, facilities and location\\nQuery: ';\nreturn [{json:{embeddingEnabled:enabled,preferenceQuery:query,candidates:enabled?candidates:[],\n  embeddingBody:{model:'embedding',encoding_format:'float',input:enabled?[instruction+bounded(query,1500),...candidates.map(c=>c.text)]:[]}}}];\n"}}, "output": [{"preferences": {"childrenBirthDates": [], "windowDays": 60, "minNights": 7, "maxNights": 14, "maxTotalDKK": 10000, "maxPerPersonNightDKK": 350, "minStars": 4, "minGuestRating": 8.4, "maxAirportKm": 80, "maxBeachMetres": 1000, "maxDeals": 3, "minPriceDropPercent": 5, "minDaytimeC": 25, "minSunshineHours": 6, "maxRainProbabilityPercent": 30, "maxRainMmPerDay": 1, "maxWindKmh": 30, "maxHistoricalWetFraction": 0.2, "weatherMode": "seasonal_allowed", "includeAllInclusivePrice": true, "preferenceQuery": "Family-friendly hotel with a pool for children and a nearby beach"}, "message": "Family holiday deals", "url": "https://www.afbudsrejser.dk/charter.json", "offers": [], "redirectUrl": "https://www.afbudsrejser.dk/charterredirect", "providerUrl": "https://www.solfaktor.dk/example", "quoteUrl": "https://www.solfaktor.dk/custom-api/yggdrasil/basket/getPackage", "quoteBody": {}, "weatherUrl": "https://api.open-meteo.com/v1/forecast", "boardOptionsUrl": "https://www.solfaktor.dk/custom-api/yggdrasil/basket/getHotelRooms", "boardCookie": "", "embeddingEnabled": true, "embeddingBody": {"model": "embedding", "encoding_format": "float", "input": ["sample query", "sample hotel"]}, "id": "sample", "channel_id": "wxrgwf839tddxyrunhbo8ernqr", "delivered": true}]});
